sp_widget.client_script:
api.controller=function() {
  /* widget controller */
  var c = this;
};

sp_widget.css:
.itam-portal-wrapper {
  padding: 40px 15px 60px;
  background-color: #f8fafc;
  font-family: inherit;
}

.hero-section {
  max-width: 750px;
  margin: 0 auto 36px;
}

.badge-pill {
  display: inline-block;
  padding: 5px 14px;
  font-size: 11px;
  font-weight: 700;
  letter-spacing: 1px;
  color: #0d9488;
  background-color: #ccfbf1;
  border-radius: 20px;
  text-transform: uppercase;
  margin-bottom: 16px;
}

.hero-icon {
  color: #334155;
  margin-bottom: 12px;
}

.hero-title {
  font-size: 34px;
  font-weight: 700;
  color: #0f172a;
  margin-bottom: 10px;
}

.hero-subtitle {
  font-size: 15px;
  color: #64748b;
  line-height: 1.6;
}

.cards-container {
  max-width: 1180px;
}

.card-col {
  margin-bottom: 24px;
}

.action-card {
  background: #ffffff;
  border: 1px solid #e2e8f0;
  border-radius: 12px;
  padding: 24px 20px;
  text-align: center;
  height: 100%;
  display: flex;
  flex-direction: column;
  justify-content: space-between;
  box-shadow: 0 4px 6px -1px rgba(0, 0, 0, 0.05);
  transition: transform 0.2s ease, box-shadow 0.2s ease;
  position: relative;
}

.action-card:hover {
  transform: translateY(-4px);
  box-shadow: 0 10px 15px -3px rgba(0, 0, 0, 0.08);
}

.live-pill {
  display: inline-block;
  font-size: 11px;
  font-weight: 600;
  padding: 3px 10px;
  border-radius: 12px;
  margin-bottom: 12px;
}

.pill-green {
  background-color: #dcfce7;
  color: #15803d;
}

.pill-amber {
  background-color: #fef3c7;
  color: #b45309;
}

.pill-blue {
  background-color: #e0f2fe;
  color: #0369a1;
}

.pill-purple {
  background-color: #f3e8ff;
  color: #7e22ce;
}

.card-icon {
  color: #0d9488;
  margin-bottom: 14px;
}

.card-title {
  font-size: 18px;
  font-weight: 600;
  color: #1e293b;
  margin-bottom: 8px;
}

.card-desc {
  font-size: 13px;
  color: #64748b;
  line-height: 1.5;
  margin-bottom: 20px;
}

.btn-action {
  border-radius: 24px;
  padding: 8px 20px;
  font-size: 13px;
  font-weight: 600;
  text-decoration: none;
  transition: all 0.2s ease;
  display: inline-block;
}

.btn-dark {
  background-color: #0f172a;
  color: #ffffff;
  border: 1px solid #0f172a;
}

.btn-dark:hover {
  background-color: #1e293b;
  color: #ffffff;
}

.btn-teal {
  background-color: #0d9488;
  color: #ffffff;
  border: 1px solid #0d9488;
}

.btn-teal:hover {
  background-color: #0f766e;
  color: #ffffff;
}

.btn-outline {
  background-color: #ffffff;
  color: #334155;
  border: 1px solid #cbd5e1;
}

.btn-outline:hover {
  background-color: #f1f5f9;
  color: #0f172a;
}
/* Amber badge for pending manager approvals */
.pill-amber {
  background-color: #fef3c7;
  color: #d97706;
  border: 1px solid #fde68a;
  font-weight: 600;
}

.btn-amber {
  background-color: #d97706;
  color: #ffffff;
  border: none;
}

.btn-amber:hover {
  background-color: #b45309;
  color: #ffffff;
}
/* Display 5 cards evenly across a single row on desktop */
@media (min-width: 992px) {
  .card-col {
    width: 20% !important;
  }
}

sp_widget.script:
(function() {
    var userId = gs.getUserID();

    // 1. Query active physical assets assigned to the logged-in user
    data.assetCount = 0;
    data.latestAssetTag = '';
    var grAsset = new GlideRecord('x_2240997_smarti_0_it_asset');
    grAsset.addQuery('assigned_to', userId);
    grAsset.addQuery('status', '!=', 'retired');
    grAsset.orderByDesc('sys_created_on');
    grAsset.query();
    data.assetCount = grAsset.getRowCount();
    if (grAsset.next()) {
        data.latestAssetTag = grAsset.getDisplayValue('asset_tag') || 'Assigned';
    }

    // 2. Query hardware requests submitted for the logged-in user
    data.openRequests = 0;
    data.completedRequests = 0;
    var grReq = new GlideRecord('x_2240997_smarti_0_hardware_request');
    grReq.addQuery('requested_for', userId);
    grReq.query();
    while (grReq.next()) {
        var state = grReq.getValue('state');
        if (state == '3' || state == 'Closed Complete') {
            data.completedRequests++;
        } else {
            data.openRequests++;
        }
    }
// Query pending approvals for the currently logged-in user
var grApp = new GlideRecord('sysapproval_approver');
grApp.addQuery('approver', gs.getUserID());
grApp.addQuery('state', 'requested');
grApp.query();
data.approvalCount = grApp.getRowCount();	
})();
